pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;
    let stream_progress = step_index as f64 / total_items as f64;

    // Penalize bins with low residual
    if bin_residual < 5 {
        score -= (10 - bin_residual) as f64 * 0.8;
    }

    // Reward bins with high capacity utilization
    if bin_capacity - bin_residual > bin_capacity / 2 {
        score += (bin_capacity - bin_residual - bin_capacity / 2) as f64 * 0.3;
    }

    // Penalize open bins above the mean residual
    if open_bins_count > mean_residual as usize {
        score -= (open_bins_count - mean_residual) as f64 * 0.5;
    }

    // Reward fitting bins beyond a certain threshold
    if fitting_bins_count > 2 {
        score += (fitting_bins_count - 2) as f64 * 0.4;
    }

    // Penalize post-residuals close to next item size
    if post_residual < next_item_size / 3 {
        score -= post_residual as f64 * 0.4;
    }

    // Reward bins with enough capacity for the next item
    if next_item_size > 0 && bin_capacity - bin_residual >= next_item_size {
        score += (bin_capacity - bin_residual - next_item_size) as f64 * 0.35;
    }

    let score = score * 0.94 + ((post_residual as f64 - (post_residual.powi(2) * stream_progress).min(1.0) + (stream_progress.powi(3) * bin_residual as f64).max(0.0)) as f64) * 0.25;

    score
}

