pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;
    let stream_progress = step_index as f64 / total_items as f64;

    // New mutation: Penalize bins with high post-residuals relative to bin capacity
    score -= (post_residual as f64 / bin_capacity as f64).powi(2) * 0.5;

    // Adjusted reward for low post-residuals
    if post_residual < item_size / 3 {
        score += (post_residual as f64 * stream_progress).powi(2) * 0.3;
    }

    // Non-linear penalty for open bins exceeding mean residual
    if open_bins_count > mean_residual as usize {
        score += ((open_bins_count - mean_residual) as f64 / mean_residual).powi(2) * 0.5;
    }

    // Reduced impact on fitting bins count
    if fitting_bins_count > 1 {
        score -= (fitting_bins_count - 1) as f64 * 0.15;
    }

    // Penalize if next item size is large and does not fit well
    if next_item_size > 0 && bin_capacity - bin_residual < next_item_size {
        score -= ((bin_capacity - bin_residual - next_item_size) as f64 / next_item_size).powi(2) * 0.1;
    }

    // Adjusted weight for stream progress and residual
    let adjusted_score = (score * 0.75 + ((post_residual as f64 - post_residual.powi(2) * stream_progress.min(1.0) + (stream_progress.powi(3) * bin_residual as f64).max(0.0)) as f64) * 0.3);

    adjusted_score
}

